{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "HSK21542, a peptide-like lysine-containing compound with multiple amides and a piperidine, showed a brain/plasma ratio of 0.001, indicating minimal BBB penetration; this directly supports poor CNS access for the query, which shares the lysine amide backbone and polar ionizable features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "A close analogue containing an N-acyl lysine linker and a C-terminal piperazine-pyridine amide showed low brain uptake after intravenous administration in rats; the query contains the same lysine linker and piperazine-pyridine motif, making this poor-permeability result highly transferable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Lisdexamfetamine, a lysine-amphetamine amide with a free primary amine, was not detected in brain tissue after oral dosing, demonstrating that the combination of a free lysine amine and amide polar surface limits CNS access; the query has an analogous free lysine side chain.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "ELN441958, which contains piperazine-pyridine and piperidine motifs similar to the query, had a brain/plasma AUC ratio of only 6.7%, classified as low permeability; this supports the expectation of inadequate CNS exposure for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Compound 11 crossed the BBB and was detected in mouse brain at 2 h, but it lacks the free lysine amine, dibromophenol, and large polar urea present in the query, so its permeability is less transferable and does not override the consistent poor-penetration evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a large, highly polar peptidomimetic with a free lysine amine, dibromophenol, urea, and piperazine-pyridine. Multiple direct CNS-exposure measurements on structurally related lysine/piperazine-pyridine compounds show negligible or low brain penetration (brain/plasma 0.001, low brain uptake, no brain detection, 6.7% AUC). The single permeable analogue lacks the key polar/ionizable lysine and urea features. Therefore, meaningful CNS access is unlikely.",
  "evidence_gaps": [
    "No direct brain/plasma, CSF, or uptake measurement exists for the query molecule itself.",
    "Morgan similarities to the most relevant evidence molecules are moderate (<0.36), so quantitative transfer is uncertain.",
    "No explicit P-gp/BCRP efflux data are available for the query or its closest analogues.",
    "No human CNS exposure data are available for query-like compounds."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

